content.text:
.arena-wrap{position:relative;width:100%;aspect-ratio:1.64;border:1px solid #47516a;border-radius:6px;overflow:hidden;background:#151e30;box-shadow:inset 0 0 20px #0008}

canvas{display:block;width:100%;height:100%;image-rendering:pixelated}

.canvas-hud{position:absolute;inset:8px 9px auto;display:flex;justify-content:space-between;pointer-events:none}

.overlay{position:absolute;inset:0;display:grid;place-items:center;background:#101525b8;backdrop-filter:blur(2px);transition:opacity .2s}

.flash{position:absolute;inset:0;pointer-events:none;background:#fff;opacity:0;transition:opacity .08s}

